const body = $json.body ?? $json;

const application = body.application ?? {};
const job = body.job ?? {};

const errors = [];

if (body.event !== 'job_application') {
  errors.push('Invalid event.');
}

if (body.version !== '1.0') {
  errors.push('Unsupported contract version.');
}

if (!job.job_id) {
  errors.push('Missing job.job_id.');
}

if (!job.job_url) {
  errors.push('Missing job.job_url.');
}

if (!application.eligible) {
  errors.push('Application item is not eligible.');
}

const allowedQueueStatuses = ['READY', 'READY_WITH_TAILORING'];

if (!allowedQueueStatuses.includes(application.queue_status)) {
  errors.push(
    `Unsupported queue_status: ${application.queue_status ?? '<missing>'}.`
  );
}

const isValidationPayload =
  job.job_id === 'n8n-local-validation-001' ||
  job.provider === 'validation';

if (isValidationPayload) {
  return [{
    json: {
      accepted: true,
      execution_mode: 'VALIDATION',
      status: 'SUBMITTED',
      message: 'Local n8n validation workflow completed.',
      metadata: {
        workflow: 'controlled-application-execution',
        test: true,
        validation_only: true,
        job_id: job.job_id,
        company: job.company ?? '',
      },
    },
  }];
}

if (errors.length > 0) {
  return [{
    json: {
      accepted: false,
      execution_mode: 'REJECTED',
      status: 'FAILED',
      message: 'Application request failed n8n contract validation.',
      metadata: {
        workflow: 'controlled-application-execution',
        validation_only: false,
        errors,
        job_id: job.job_id ?? '',
      },
    },
  }];
}

return [{
  json: {
    accepted: true,
    execution_mode: 'CONTROLLED',
    status: 'READY',
    message: 'Application request passed n8n execution gates. No external application was submitted.',
    metadata: {
      workflow: 'controlled-application-execution',
      validation_only: false,
      external_submission: false,
      next_stage: 'application-automation-adapter',
      job_id: job.job_id,
      company: job.company ?? '',
      title: job.title ?? '',
      job_url: job.job_url,
      queue_status: application.queue_status,
      readiness_decision: application.readiness_decision,
    },
  },
}];
